			<?php if ( $groups ) : ?><div class="bo-price-editor"><h4>Prices by customer group</h4><p>Set a price for any group. Leave a price blank if it has no special price yet.</p><div class="bo-price-grid"><?php foreach ( $groups as $group ) : $stored = $form_source ? get_post_meta( $form_source->ID, '_bo_group_prices', true ) : array(); $stored = is_array( $stored ) ? $stored : array(); ?><label><?php echo esc_html( $group->post_title ); ?><span class="bo-money-input"><span>$</span><input name="group_prices[<?php echo esc_attr( $group->ID ); ?>]" type="number" min="0" step="0.01" value="<?php echo esc_attr( isset( $stored[ $group->ID ] ) ? $stored[ $group->ID ] : '' ); ?>" placeholder="0.00"></span></label><?php endforeach; ?></div></div><?php endif; ?>
			<div class="bo-form-actions"><button class="bo-button bo-primary" type="submit" name="save_product" value="1">Save Product</button><?php if ( ! $editing ) : ?><button class="bo-button" type="submit" name="save_and_add" value="1">Save &amp; Add Another</button><?php endif; ?><a class="bo-button bo-quiet" href="<?php echo esc_url( add_query_arg( array( 'bakery_dashboard' => '1', 'view' => 'products' ), home_url( '/' ) ) ); ?>">Cancel</a></div></form>
		</div>
		<?php if ( ! $form_source ) : ?>
		<?php if ( ! $products ) : ?><div class="bo-empty-state"><span><?php echo bakery_ordering_icon( 'croissant' ); ?></span><h3>Your catalog is ready for its first product</h3><p>Add a product, upload a photo, and set its selling unit and customer group prices.</p><button type="button" class="bo-button bo-primary" data-bo-open-form="product">Add Your First Product</button></div><?php else : ?><div class="bo-product-grid"><?php foreach ( $products as $product ) : if ( ( $editing && (int) $product->ID === (int) $editing->ID ) || ( $duplicate_source && (int) $product->ID === (int) $duplicate_source->ID ) ) { continue; } $prices = get_post_meta( $product->ID, '_bo_group_prices', true ); $prices = is_array( $prices ) ? $prices : array(); $product_unit = get_post_meta( $product->ID, '_bo_pack_label', true ) ?: get_post_meta( $product->ID, '_bo_unit', true ) ?: 'Each'; if ( in_array( strtolower( $product_unit ), array( 'each', 'individually' ), true ) ) { $product_unit = 'Each'; } $unit_suffix = bakery_ordering_product_unit_suffix( $product_unit ); ?><article class="bo-product-card">
				<a class="bo-card-open" href="<?php echo esc_url( add_query_arg( array( 'bakery_dashboard' => '1', 'view' => 'products', 'edit_product' => $product->ID ), home_url( '/' ) ) ); ?>" aria-label="Edit details for <?php echo esc_attr( $product->post_title ); ?>"></a>
				<div class="bo-product-photo">
					<?php if ( has_post_thumbnail( $product ) ) { echo get_the_post_thumbnail( $product, 'large' ); } else { echo bakery_ordering_icon( 'croissant' ); } ?>
					<div class="bo-card-tools">
						<a class="bo-card-tool bo-card-duplicate" href="<?php echo esc_url( add_query_arg( array( 'bakery_dashboard' => '1', 'view' => 'products', 'duplicate_product' => $product->ID ), home_url( '/' ) ) ); ?>" aria-label="Duplicate <?php echo esc_attr( $product->post_title ); ?>" title="Duplicate product"><?php echo bakery_ordering_icon( 'duplicate' ); ?></a>
						<a class="bo-card-tool bo-card-edit" href="<?php echo esc_url( add_query_arg( array( 'bakery_dashboard' => '1', 'view' => 'products', 'edit_product' => $product->ID ), home_url( '/' ) ) ); ?>" aria-label="Edit <?php echo esc_attr( $product->post_title ); ?>" title="Edit product"><?php echo bakery_ordering_icon( 'edit' ); ?></a>
						<form method="post" action="<?php echo esc_url( $url ); ?>" data-bo-confirm="Delete this product from the catalog?">
							<input type="hidden" name="bakery_ordering_action" value="delete_product">
							<input type="hidden" name="product_id" value="<?php echo esc_attr( $product->ID ); ?>">
							<?php wp_nonce_field( 'bakery_ordering_catalog_delete_product' ); ?>
							<button class="bo-card-tool bo-card-delete" type="submit" aria-label="Delete <?php echo esc_attr( $product->post_title ); ?>" title="Delete product"><?php echo bakery_ordering_icon( 'delete' ); ?></button>
						</form>
					</div>
					<span class="bo-product-unit"><?php echo esc_html( 'Sold ' . strtolower( $product_unit ) . ' · multiples of ' . max( 1, absint( get_post_meta( $product->ID, '_bo_pack_quantity', true ) ) ) ); ?></span>
				</div>
				<div class="bo-product-details">
					<div class="bo-product-title-row">
						<div><h3><?php echo esc_html( $product->post_title ); ?></h3>
						<?php if ( get_post_meta( $product->ID, '_bo_sku', true ) ) : ?><p class="bo-sku">SKU <?php echo esc_html( get_post_meta( $product->ID, '_bo_sku', true ) ); ?></p><?php endif; ?></div>
					</div>
					<p class="bo-product-description"><?php echo esc_html( wp_trim_words( $product->post_content, 16 ) ); ?></p>
					<?php $assigned_categories = wp_get_object_terms( $product->ID, 'bo_product_category' ); ?>
					<div class="bo-product-prices">
						<div class="bo-card-price-category-row"><?php if ( is_array( $assigned_categories ) && $assigned_categories ) : ?><div class="bo-product-category-chips" aria-label="Product categories"><?php foreach ( $assigned_categories as $assigned_category ) : ?><button type="button" class="bo-product-category-chip" data-bo-edit-card-category data-category-id="<?php echo esc_attr( $assigned_category->term_id ); ?>" data-category-name="<?php echo esc_attr( $assigned_category->name ); ?>" aria-label="Edit category <?php echo esc_attr( $assigned_category->name ); ?>"><?php echo esc_html( $assigned_category->name ); ?></button><?php endforeach; ?></div><?php else : ?><button type="button" class="bo-card-add-category" data-bo-open-card-category>+ Category</button><?php endif; ?><span class="bo-base-price"><strong><?php echo '' !== get_post_meta( $product->ID, '_bo_base_price', true ) ? '$' . esc_html( get_post_meta( $product->ID, '_bo_base_price', true ) ) : '—'; ?><small<?php echo '' !== get_post_meta( $product->ID, '_bo_base_price', true ) ? '' : ' hidden'; ?>> / <?php echo esc_html( $unit_suffix ); ?></small></strong></span></div>
						<?php foreach ( $groups as $group ) : if ( isset( $prices[ $group->ID ] ) ) : ?><span><?php echo esc_html( $group->post_title ); ?><strong>$<?php echo esc_html( $prices[ $group->ID ] ); ?><small> / <?php echo esc_html( $unit_suffix ); ?></small></strong></span><?php endif; endforeach; ?>
					</div>
					<?php if ( ! is_array( $assigned_categories ) || ! $assigned_categories ) : ?><form method="post" class="bo-card-category-popover" data-bo-card-category-popover hidden action="<?php echo esc_url( $url ); ?>"><input type="hidden" name="bakery_ordering_action" value="assign_product_category"><input type="hidden" name="product_id" value="<?php echo esc_attr( $product->ID ); ?>"><?php wp_nonce_field( 'bakery_ordering_catalog_assign_product_category' ); ?><?php if ( $product_categories ) : ?><label>Choose a category<select name="category_id"><option value="">Select category</option><?php foreach ( $product_categories as $category ) : ?><option value="<?php echo esc_attr( $category->term_id ); ?>"><?php echo esc_html( $category->name ); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Create a new category<input type="text" name="new_category_name" maxlength="80" placeholder="e.g. Pastries"></label><button class="bo-button bo-primary" type="submit">Add to Product</button></form><?php endif; ?>
					<?php if ( is_array( $assigned_categories ) && $assigned_categories ) : ?><form method="post" class="bo-card-category-popover bo-card-category-edit-popover" data-bo-card-category-edit-popover hidden action="<?php echo esc_url( $url ); ?>"><input type="hidden" name="bakery_ordering_action" value="edit_product_category"><input type="hidden" name="product_id" value="<?php echo esc_attr( $product->ID ); ?>"><input type="hidden" name="term_id" value="" data-bo-edit-category-id><?php wp_nonce_field( 'bakery_ordering_catalog_edit_product_category' ); ?><label>Category name<input type="text" name="category_name" maxlength="80" data-bo-edit-category-name required></label><div class="bo-category-edit-actions"><button class="bo-button bo-primary" type="submit" name="category_operation" value="rename_category">Rename category</button><button class="bo-button bo-category-remove-action" type="submit" name="category_operation" value="remove_from_product">Remove from product</button></div></form><?php endif; ?>
				</div>
			</article><?php endforeach; ?></div><?php endif; ?>
		<?php endif; ?>
		</section><?php endif; ?>
		<p class="bo-catalog-footer">Bakery catalog · Customer accounts and WooCommerce connection will be added in a later phase.</p>
	</main>
</div>
